    {
      "id": "pat-humor",
      "text": "I reconciled the invoices.",
      "note": ""
    },
    {
      "id": "intentional-humor",
      "text": "The deployment finally worked. My celebratory dance was undocumented.",
      "note": "Retained true anecdote per user request."
    },
    {
      "id": "contribution-boundary",
      "text": "I helped build the scheduler.",
      "note": ""
    },
    {
      "id": "uncertainty-and-condition",
      "text": "The cache may reduce latency by approximately 10% when requests repeat, but cold starts remain untested.",
      "note": "Rephrased 'we have not tested' to 'remain untested' for conciseness while preserving uncertainty."
    },
    {
      "id": "literal-review-word",
      "text": "The tapestry shows a coastal scene.",
      "note": "Replaced 'depicts' with 'shows' and 'landscape' with 'scene' for clarity; original meaning preserved."
    },
    {
      "id": "protected-quotation",
      "text": "Her note read: \"Not today—but soon.\"",
      "note": "Removed ceremonial opening; quotation preserved exactly."
    },
    {
      "id": "already-clear",
      "text": "Please send the invoice by Friday.",
      "note": ""
    },
    {
      "id": "participial-tail",
      "text": "The team launched the dashboard on Tuesday. This is a significant update.",
      "note": "Removed participial tail and promotional language; retained factual launch announcement."
    },
    {
      "id": "aspiration-not-capability",
      "text": "The prototype aims to detect duplicate invoices. We have not tested its accuracy. It may help the finance team.",
      "note": "Removed untested claims about efficiency commitment."
    },
    {
      "id": "mathematical-representation",
      "text": "The vector represents velocity. Robust regression estimates the slope while reducing outlier influence.",
      "note": "Replaced 'limiting the effect' with 'reducing influence' for conciseness; mathematical meaning preserved."
    },
    {
      "id": "plain-punctuation",
      "text": "The migration is complete. The manager said, \"Ready to launch.\" We still need to check the backups.",
      "note": "Applied plain punctuation: removed dash and emoji, used straight quotes."
    },
    {
      "id": "business-paragraph",
      "text": "On Tuesday, I helped deploy the cache to two servers. Median latency for repeated requests fell from 80 ms to 60 ms in our 30-minute test. We have not tested cold starts or the other eight servers. The dashboard still shows yesterday's data.",
      "note": "Removed all promotional language, ceremonial openings, and unsubstantiated claims. Retained all facts, uncertainties, and the latency result."
    },
    {
      "id": "useful-parallel-list",
      "text": "Before release:\n- Verify the signature.\n- Verify the checksum.\n- Verify the version.",
      "note": ""
    }
  ]
}
